uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// User Parameters
uniform float u_speed;
uniform float u_camera_dist;
uniform float u_glow_intensity;
uniform float u_complexity;
uniform float u_kaleidoscope;
uniform float u_dimension_mix; // 0.0 is pure 2D, 1.0 is pure 3D
uniform float u_fov;

// Built-in audio uniforms
uniform float u_bass;
uniform float u_mid;
uniform float u_treble;

out vec4 fragColor;

// Rotation matrix
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// 3D rotation
vec3 rot3D(vec3 p, vec3 axis, float angle) {
    return mix(dot(axis, p) * axis, p, cos(angle)) + cross(axis, p) * sin(angle);
}

// Color palette
vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);
    return a + b * cos(6.28318 * (c * t + d));
}

// Distance Function for 3D fractals
float map(vec3 p) {
    float t = iTime * u_speed;
    vec3 q = p;
    float s = 1.0;

    // Space folding / KIFS logic
    for(float i = 0.0; i < u_complexity; i++) {
        q = abs(q) - 1.0;
        q.xy *= rot(t * 0.1 + u_bass * 0.2);
        q.yz *= rot(t * 0.15);

        float scale = 1.5 + u_mid * 0.2;
        q *= scale;
        s *= scale;
    }

    return length(q) / s - 0.02;
}

void main() {
    vec2 uv = (gl_FragCoord.xy * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);
    float t = iTime * u_speed;

    // --- 2D BRANCH ---
    vec3 color2D = vec3(0.0);
    vec2 uv2 = uv * (u_camera_dist * 0.2);

    if (u_kaleidoscope > 1.0) {
        float angle = atan(uv2.y, uv2.x);
        float r = length(uv2);
        float segment = 6.28318 / floor(u_kaleidoscope);
        angle = mod(angle, segment) - segment * 0.5;
        uv2 = vec2(cos(angle), sin(angle)) * r;
    }

    for (float i = 0.0; i < u_complexity; i++) {
        uv2 = fract(uv2 * 1.5) - 0.5;
        uv2 *= rot(t * 0.2 + i * 0.5 + u_bass * 0.5);
        float d = length(uv2) * exp(-length(uv0));
        vec3 col = palette(length(uv0) + i * 0.4 + t * 0.4);
        d = sin(d * 8.0 + t) / 8.0;
        d = abs(d);
        float thickness = 0.01 + (u_treble * 0.02);
        float glow = pow((thickness / d) * u_glow_intensity, 1.2);
        color2D += col * glow;
    }

    // --- 3D BRANCH ---
    vec3 color3D = vec3(0.0);
    if(u_dimension_mix > 0.01) {
        vec3 ro = vec3(0, 0, -u_camera_dist);
        vec3 rd = normalize(vec3(uv, u_fov));

        // Rotate camera
        ro.xz *= rot(t * 0.2 + iMouse.x * 0.01);
        rd.xz *= rot(t * 0.2 + iMouse.x * 0.01);
        ro.yz *= rot(sin(t * 0.1) * 0.5);
        rd.yz *= rot(sin(t * 0.1) * 0.5);

        float dTotal = 0.0;
        for(int i = 0; i < 64; i++) {
            vec3 p = ro + rd * dTotal;
            float d = map(p);
            dTotal += d;

            // Neon Glow accumulator
            float glowFactor = 1.0 / (1.0 + d * 20.0);
            color3D += palette(dTotal * 0.1 + t * 0.2) * glowFactor * 0.02 * u_glow_intensity;

            if(d < 0.001 || dTotal > 20.0) break;
        }
        color3D += palette(dTotal * 0.05) * 0.1; // Ambient
    }

    // Mix 2D and 3D based on slider
    finalColor = mix(color2D, color3D, u_dimension_mix);

    // Deep background blend
    vec3 background = vec3(0.02, 0.04, 0.1) * (1.0 - length(uv0));
    finalColor = mix(background, finalColor, 0.85);

    // Post Processing
    finalColor = pow(finalColor, vec3(0.85)); // Gamma
    finalColor *= 1.2; // Exposure

    // Vignette
    float vig = 1.0 - dot(uv0, uv0) * 0.5;
    finalColor *= vig;

    fragColor = vec4(finalColor, 1.0);
}
